import json
from pathlib import Path
p=Path(__file__).resolve().parent/'translations/ro/full/chunks'
t={
 't000022':'În zilele următoare, Bilbo avea să pornească într-o misiune care nu numai că îi va încerca curajul, ci îi va dezvălui și adevărata putere a prieteniei și unității. Nu știa că aventura va împleti destinele multora și va duce la o bătălie mai mare decât și-ar fi putut închipui.',
 't000023':'Capitolul doi — Misiunea frăției: adunarea echipei ideale!',
 't000024':'Cu un nou sentiment al rostului, trezit de harta străveche, Bilbo Baggins stătea în pragul aventurii. Lumea de dincolo de îndrăgitul Comitat îl chema, dar știa că nu putea înfrunta singur necunoscutul. Venise timpul să adune o frăție — un grup de suflete curajoase care să îi stea alături când vor descifra misterele tărâmului ascuns. „Gandalf, pe cine să chemăm?”, întrebă Bilbo, cu mintea plină de posibilități. Vrăjitorul își mângâie barba pe gânduri, cu ochii sclipind ștrengărește. „Avem nevoie de o ceată variată — fiecare trebuie să aducă o pricepere aparte. Să începem cu cei care s-au dovedit deja”, răspunse el, cu un strop de nostalgie. „Îl avem pe Aragorn, străjerul din Nord, și pe Legolas, elful neîntrecut la trasul cu arcul.',
 't000025':'Nu îl putem uita pe Gimli, piticul a cărui loialitate și vitejie nu au seamăn. Și, desigur, Frodo și Sam trebuie să vină cu noi. Au străbătut deja locuri îndepărtate.” Bilbo simți cum îl cuprinde entuziasmul imaginându-și reîntâlnirea vechilor prieteni. Fiecare avea calități proprii: curajul și capacitatea de a conduce ale lui Aragorn, privirea ageră și agilitatea lui Legolas, statornicia lui Gimli și loialitatea neclintită a lui Frodo și Sam. Împreună puteau descuia tainele tărâmului ascuns și apăra Pământul de Mijloc de întunericul care se apropia. Cu planul făcut, Bilbo nu mai pierdu vremea. El și Gandalf porniră să adune frăția, începând cu Aragorn, cunoscut drept Pas Mare. Au mers la marginea așezării Bree, unde umbrele copacilor se amestecau cu ceața serii.',
 't000026':'Apropiindu-se de han, auzeau râsetele și muzica venind dinăuntru.',
 't000027':'„Ah, Poneiul Săltăreț”, spuse Bilbo zâmbind. „Ce amintiri frumoase am de aici!” Intrară în han, unde lumina caldă a felinarelor cădea peste mulțimea veselă. Bilbo îl zări pe Aragorn la o masă din colț, adâncit în vorbă cu câțiva călători. Se apropie, iar străjerul ridică privirea și zâmbi larg pe chipul său aspru. „Bilbo! Gandalf! Ce vă aduce aici?”, strigă Aragorn, ridicându-se să îi îmbrățișeze. „A trecut prea mult de la ultima noastră aventură.” După saluturi, Bilbo trecu direct la rostul vizitei. Îi arătă harta și îi povesti despre însemnătatea tărâmurilor ascunse și misiunea care îi aștepta. Ochii lui Aragorn se lărgiră de interes când cercetă harta. „O călătorie în necunoscut, spui? Mă alătur vouă.',
 't000028':'Miza este mare și îmi voi pune bucuros sabia în slujba acestei cauze.”',
 't000029':'Cu Aragorn alături, cei trei porniră să îl caute pe Legolas și călătoriră spre tărâmul elfilor de la Vâlceaua Despicată. Pădurea era plină de culori vii, iar cântecul păsărilor răsuna împrejur. Bilbo simțea crescând între ei prietenia, întărită de emoția așteptării. Când ajunseră la Vâlceaua Despicată, îi întâmpină frumusețea liniștită a orașului elfesc. Legolas, cu părul lung și ochii ageri, se apropie zâmbind. „Am simțit că veniți, dragi prieteni. Ce vă aduce la mine?” Bilbo le povesti misiunea, însemnătatea hărții și nevoia de priceperea lui. Legolas acceptă fără ezitare, bucuros să pornească într-o nouă aventură. Apoi merseră spre munți ca să îl găsească pe Gimli.',
 't000030':'După câteva zile de drum, ajunseră la sălile piticilor. Gimli se afla în mijlocul unui ospăț mare, iar zăngănitul cupelor și râsetele umpleau încăperea. Când îl văzu pe Bilbo, chipul i se lumină. „Bilbo! Ce surpriză! Vino să bem ceva!”, strigă Gimli.',
 't000031':'După râsete din toată inima și un toast pentru prietenie, Bilbo le înfățișă misiunea. Gimli declară cu entuziasmul său obișnuit: „N-aș lipsi pentru nimic în lume! Toporul meu va fi alături de tine!” Pe măsură ce grupul prindea contur, Bilbo simțea o căldură crescând în sine. Fiecare venea cu propria poveste și putere, iar împreună aveau să formeze o legătură de nezdruncinat. Cu frăția aproape întreagă, se întoarseră în Comitat după Frodo și Sam. Inima lui Bilbo bătea tare când le ciocăni la ușă, nerăbdător să le dea vestea. Când Frodo deschise, surpriza îi lăsă loc entuziasmului. „O aventură, unchiule Bilbo? Vin și eu!”, strigă Frodo, iar în spatele lui Sam stătea cu ochii mari, plini de hotărâre. „Nu-l voi lăsa pe domnul',
 't000032':'Frodo să plece singur, nici gând!”, stărui Sam, înfigându-și bine picioarele în pământ. „Oriunde mergi, merg și eu.” Cu Frodo și Sam alături, se strânseră din nou în jurul hărții. Gandalf o întinse pe masă și arătă drumurile și reperele. „Trebuie să plecăm în zori. Timpul ne presează și nu putem întârzia.” Frăția simți povara misiunii, dar și fiorul entuziasmului. Până târziu în noapte și-au spus povești și au râs, amintindu-și aventurile trecute și visând la ce-i aștepta. În timp ce focul trosnea, Bilbo își privi însoțitorii: fiecare era pregătit pentru încercările ce aveau să vină.',
 't000033':'Comitatul fusese mereu un adăpost sigur, dar acum părea punctul de plecare spre ceva mult mai mare. Când se crăpă de ziuă și cerul se coloră în portocaliu și roz, membrii frăției își pregătiră lucrurile, cu emoție și teamă amestecate. Nu mai erau doar un grup de prieteni; erau o echipă unită de un scop comun, fiecare purtând pe umeri greutatea lumii. Aruncând o ultimă privire Comitatului pașnic, trecură dincolo de hotarele lui și porniră într-o călătorie plină de incertitudine și promisiuni. Intrând în ținuturile sălbatice ale Pământului de Mijloc, știau că încercările viitoare le vor testa puterea și vor adânci prietenia care avea să devină cea mai bună armă împotriva întunericului.',
 't000034':'Nu știau că adevăratele greutăți abia începeau și că tărâmul ascuns îi aștepta, gata să își dezvăluie tainele și să le încerce hotărârea.',
 't000035':'Capitolul trei — Încercările tărâmului ascuns: secrete și sacrificii',
 't000036':'Când frăția lăsă în urmă dealurile cunoscute ale Comitatului, aerul se umplu de fiorul aventurii. Verdeața bogată cedă locul unor ținuturi stâncoase, iar poteca deveni tot mai primejdioasă. Fiecare pas îi ducea mai adânc în necunoscut, unde printre copaci păreau să plutească șoapte de pericol. Primele zile trecură într-un vârtej de uimire și emoție. Străbătură păduri dese, dealuri pietroase și râuri șerpuite. Frodo și Sam admirau frumusețea uluitoare a Pământului de Mijloc, în timp ce Gimli istorisea cu mândrie întâmplări din trecutul piticilor. Legolas, mereu atent, le arăta minunile ascunse — plante rare și făpturi greu de zărit — dezvăluind magia peisajului pe care mulți o treceau cu vederea. Dar, pe măsură ce se depărtau de Comitat, umbrele se lungeau și atmosfera devenea tot mai amenințătoare.',
 't000037':'Într-o seară, pe când își așezau tabăra sub stele, purtarea lui Gandalf se schimbă. Își încruntă sprâncenele, ca și cum ar fi simțit o prezență la marginea privirii lor. „Stați aproape”, îi avertiză cu voce joasă. „Drumul din față poate să nu fie atât de prietenos cum pare.” Frăția se pregăti de noapte, dar somnul veni greu. Frodo zăcea treaz, privind pâlpâirea focului și simțind o apăsare inexplicabilă pe inimă. Curând, tăcerea stranie fu sfâșiată de foșnetul frunzelor și de șoapte slabe, de parcă pădurea însăși ar fi ascuns taine. Dintr-odată, din umbre se ivi o siluetă întunecată, care îi trecu cu fiori: un spectru, unul dintre slujitorii lui Sauron, atras de prezența Inelului.',
 't000038':'Panica îi cuprinse când făptura învelită în întuneric înaintă. „Faceți un cerc!”, porunci Aragorn, cu vocea fermă în ciuda încordării. Frăția se strânse repede, scoase armele și se pregăti să se apere. Inima lui Frodo bătea nebunește când simți chemarea Inelului, o ispită mai puternică decât trăise vreodată. „Nu trebuie să cedez!”, gândi el, luptând cu atracția sinistră. Când spectrul se repezi, frăția trecu la luptă. Legolas trimise săgeți cu o precizie uimitoare și fiecare își găsi ținta. Gimli se avântă cu toporul ridicat, iar Aragorn luptă vitejește, cu sabia sclipind în lumina lunii. Bătălia fu aprigă, dar scurtă: prin colaborare și curaj, izbutiră să împingă făptura înapoi în umbre. Gâfâind și zguduiți, se strânseră din nou.',
 't000039':'„Trebuie să fim mai vigilenți”, îi sfătui Gandalf, cercetând întunericul. „Acesta este doar începutul încercărilor.” Întâlnirea îi tulbură pe toți, dar le întări hotărârea. Mai departe îi așteptară multe obstacole: teren primejdios, furtuni neașteptate și chiar fiare sălbatice. Fiecare încercare le atinse limitele și îi apropie. Învățară să se sprijine unul pe altul, recunoscând priceperea aparte a fiecăruia. Într-o noapte cu furtună puternică găsiră adăpost într-o peșteră, unde își împărtășiră povești și temeri. Loialitatea lui Sam străluci când îl liniști pe Frodo, amintindu-i că nu era singur în această luptă. „O vom înfrunta împreună, domnule Frodo”, îl asigură cu glas hotărât.',
 't000040':'Gandalf profită de prilej ca să le istorisească vechi povești despre tărâmurile ascunse și să le explice însemnătatea în lupta cu întunericul. Vorbi despre nevoia de unitate și sacrificiu, subliniind că puterea frăției nu stătea numai în aptitudinile fiecăruia, ci și în devotamentul lor unii față de alții. Zilele se făcură săptămâni, iar frăția se întări, dar crescu și sentimentul că timpul îi presa. Aflaseră multe despre tărâmul căutat și știau de primejdiile care îi urmăreau. Șoaptele despre întuneric se răspândeau peste ținuturi, iar vremea se scurgea. În cele din urmă, după un răstimp ce păru o veșnicie, ajunseră la intrarea în tărâmul ascuns — o uriașă arcadă de piatră, împodobită cu sculpturi complicate care păreau să pulseze de magie străveche.',
 't000041':'Îi cuprinse uimirea când se opriră înaintea arcadei, cu greutatea călătoriei apăsându-le umerii. „Aici este”, șopti Bilbo. „Cheia descifrării tainelor.” Aragorn păși în față și cercetă sculpturile. „Trebuie să fim prudenți. Tărâmul acesta are propriile încercări și nu putem presupune că ne va primi cu brațele deschise.” Trecând pragul, fură învăluiți de o lumină tainică, opusă întunericului întâlnit până atunci. Tărâmul ascuns li se arătă în toată splendoarea: copaci înalți cu frunze sclipitoare, râuri cu apă limpede ca cristalul și făpturi cunoscute sau stranii. Era un loc fermecat, dar frăția știa că primejdia se ascundea încă acolo.',
 't000042':'Pe măsură ce înaintau în tărâmul ascuns, aerul părea încărcat de energie, iar rostul misiunii devenea mai limpede. Fiecare pas purta promisiunea descoperirii, dar membrii frăției simțeau puternic sacrificiile deja făcute și pe cele ce îi mai așteptau. Nu știau că cea mai grea încercare era în fața lor și avea să le testeze nu doar puterea, ci chiar legăturile de prietenie pe care le închegaseră. În inima tărâmului ascuns urmau să facă alegeri care le vor hotărî soarta și pe cea a Pământului de Mijloc. Cu hotărârea înnoită, merseră înainte, gata să dezlege misterele din adâncul acelei lumi magice.',
 't000043':'Capitolul patru — Revelația finală: lumina împotriva întunericului',
 't000044':'Când frăția pătrunse mai adânc în tărâmul ascuns, fu învăluită de un peisaj uluitor, sclipind de magie și taine străvechi. Copaci uriași se ridicau spre cer, frunzele lor luminând blând podeaua pădurii. Pâraie cu apă limpede ca cristalul șerpuiau printre ei, cântând ca și cum ar fi urmat bătaia inimii pământului. Sub frumusețea locului se simțea însă o tensiune apăsătoare, care le amintea că nu erau singuri. Gandalf îi conduse mai departe spre o poiană măreață, unde se afla un piedestal mare de piatră, împodobit cu sculpturi complicate și rune luminoase. Aerul vibra de energie, iar toți simțeau că erau în pragul unui eveniment însemnat. „Aici este”, spuse Gandalf cu respect în glas.',
 't000045':'„Piedestalul acesta păstrează cheia tainelor tărâmului ascuns. Dar trebuie să fim pregătiți; întunericul nu ne va lăsa să îi luăm puterea cu ușurință.” Frăția se strânse în jurul pietrei, cu inimile bătând de așteptare și teamă. Bilbo păși înainte, simțind o legătură stranie cu piatra veche. Cercetând sculpturile, recunoscu semnele de pe harta găsită de el — cheia care lega misiunea lor de tărâmul ascuns. „Aici trebuie să intre cheia”, spuse Bilbo, cu entuziasm în glas. „Dar cum o descuiem?” Înainte ca Gandalf să răspundă, un mârâit jos răsună prin poiană și le trimise fiori pe șira spinării. Întorcându-se, văzură siluete ieșind dintre copaci — făpturi acoperite de întuneric, care răspândeau răutate.',
 't000046':'Erau slujitorii lui Sauron, atrași de prezența frăției. „Apărați-vă!”, strigă Aragorn, scoțând sabia, iar grupul se așeză în formație de apărare. Rămaseră neclintiți, uniți printr-o legătură mai puternică decât frica ce amenința să îi cuprindă. Lupta izbucni, iar haosul se roti în jurul lor. Legolas se mișca sprinten printre umbre, trimițând săgeți precise, în timp ce toporul lui Gimli se legăna cu putere și îi dobora pe dușmani. Frodo și Sam luptau unul lângă altul, fără să își piardă curajul în fața întunericului copleșitor. Bilbo stătea la piedestal, cu inima bătând nebunește. Simțea puterea pietrei, dar știa că trebuiau să îi descuie tainele ca să întoarcă soarta bătăliei. Amintindu-și harta, căută în grabă semnele care se potriveau cu cele de pe piedestal.',
 't000047':'„Gandalf!”, strigă Bilbo peste zgomotul luptei. „Ce trebuie să fac?”',
}
for n in range(3,6):
 x=p/f'{n:04d}.json';d=json.loads(x.read_text());changed=False
 for s in d['segments']:
  if s['id'] in t:
   assert not s['translation'] or s['translation']==t[s['id']]
   s['translation']=t[s['id']];changed=True
 if changed:x.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
